@model CreateLessonViewModel
@{ ViewData["Title"] = "Create lesson"; }
<section class="auth-wrap"><div class="card auth-card"><h1>Create lesson</h1><form asp-action="CreateLesson" method="post" class="form">@Html.AntiForgeryToken()<label asp-for="ModuleId">Module</label><select asp-for="ModuleId" asp-items="Model.Modules"></select><span asp-validation-for="ModuleId" class="field-error"></span><label asp-for="Title"></label><input asp-for="Title" /><span asp-validation-for="Title" class="field-error"></span><label asp-for="Summary"></label><textarea asp-for="Summary" rows="3"></textarea><span asp-validation-for="Summary" class="field-error"></span><label asp-for="VideoUrl"></label><input asp-for="VideoUrl" /><span asp-validation-for="VideoUrl" class="field-error"></span><label asp-for="ContentHtml">Lesson content (HTML)</label><textarea asp-for="ContentHtml" rows="10"></textarea><span asp-validation-for="ContentHtml" class="field-error"></span><div class="row top-gap"><a asp-action="Index" class="btn ghost">Back</a><button type="submit" class="btn">Save lesson</button></div></form></div></section>
@section Scripts { <partial name="_ValidationScriptsPartial" /> }
